81	/**
82	 * The values an operator may declare, each replacing one reading this stage
83	 * would otherwise have to make. Every one of them is `null` by default, and a
84	 * `null` this stage cannot fill by reading the tree is a refusal.
85	 */
86	export type IngestDeclarations = Readonly<{
87		id: string | null;
88		frontendRoot: string | null;
89		revision: string | null;
