115		commitShaSource: ValueSource;
116		/** Which file the revision was read out of, when it was read. */
117		commitShaReadFrom: string | null;
118	}>;
119	
120	export type IngestTreeReading = Readonly<{
121		files: number;
122		bytes: number;
123		/** The digest of the sorted `path sha256 bytes` manifest of the tree. */
124		normalizedManifestSha256: string;
125	}>;
126	
127	export type IngestRecord = Readonly<{
128		stage: 'ingest';
129		schemaVersion: string;
130		ran: boolean;
131		/** Why the stage did not run, when it did not. */
132		reason: string | null;
133		id: string | null;
134		idSource: ValueSource | null;
135		/** The frontend root, relative to the source root. */
136		frontendRoot: string | null;
137		frontendRootSource: ValueSource | null;
138		pin: IngestPin | null;
139		tree: IngestTreeReading | null;
140		detected: ApplicationAnalysis | null;
141		licence: LicenceAtPinRecord | null;
142		closure: LegacyClosureRecord | null;
143		/** Why there is no closure record, when there is none. */
144		closureReason: string | null;
145		notEstablished: readonly string[];
146	}>;
147	
148	const INGEST_NOT_ESTABLISHED: readonly string[] = Object.freeze([
149		'An ingest record states what the source on disk says at the revision it was pinned to. It is not an acquisition: nothing here establishes that these bytes are the bytes the named repository publishes at that revision, and no archive was fetched, reconciled against a Git tree, or double-streamed by this stage.',
150		'`normalizedManifestSha256` digests the files this stage walked. Installed packages and Git metadata are not walked, so the digest is comparable with another walk of the same shape and not with a digest taken over a whole archive.',
151		'The closure reading is the dependency tree the lockfile itself carries. A lockfile that records its closure only in the `packages` map yields no placements here, and a count of zero placements is the absence of a reading rather than an empty closure.',
152		'Nothing here installs, builds, or runs the application. An admitted application is one whose identity, pin, licence and declared closure were read — not one that was shown to work.',
153		'No era cell was chosen or provisioned. Which Node and toolchain era this source needs is not read here and not established by admission.',
154		'A value recorded with source `declared` was supplied by an operator. This stage did not read it and does not corroborate it.',
155	]);
156	
157	/** The record for a stage the run did not ask for. */
158	export function ingestNotRequested(reason: string): IngestRecord {
159		return Object.freeze({
160			stage: 'ingest',
161			schemaVersion: INGEST_RECORD_SCHEMA,
162			ran: false,
163			reason,
164			id: null,
165			idSource: null,
166			frontendRoot: null,
167			frontendRootSource: null,
168			pin: null,
169			tree: null,
170			detected: null,
171			licence: null,
172			closure: null,
173			closureReason: null,
174			notEstablished: INGEST_NOT_ESTABLISHED,
175		});
176	}
177	
178	/**
179	 * The commit a checkout is sitting on, read from its own Git metadata.
180	 *
181	 * Returns the sha and the file it came out of, or `null` when the tree carries
182	 * no readable Git metadata — which is a refusal upstream, not a default.
183	 */
184	export async function readGitRevision(
185		sourceRoot: string,
186	): Promise<Readonly<{ commitSha: string; readFrom: string }> | null> {
187		const gitDir = path.join(sourceRoot, '.git');
188		if (!(await directoryExists(gitDir))) return null;
189		const headFile = path.join(gitDir, 'HEAD');
190		if (!(await fileExists(headFile))) return null;
191		const head = (await readFile(headFile, 'utf8')).trim();
192		if (!head.startsWith('ref: '))
193			return lowerHex40.test(head) ? { commitSha: head, readFrom: '.git/HEAD' } : null;
194		const reference = head.slice('ref: '.length).trim();
195		const looseFile = path.join(gitDir, reference);
196		if (await fileExists(looseFile)) {
197			const sha = (await readFile(looseFile, 'utf8')).trim();
198			if (lowerHex40.test(sha)) return { commitSha: sha, readFrom: `.git/${reference}` };
199			return null;
200		}
201		const packedFile = path.join(gitDir, 'packed-refs');
202		if (!(await fileExists(packedFile))) return null;
203		for (const line of (await readFile(packedFile, 'utf8')).split('\n')) {
204			if (line.startsWith('#') || line.startsWith('^')) continue;
205			const [sha, name] = line.trim().split(' ');
206			if (name === reference && sha !== undefined && lowerHex40.test(sha))
207				return { commitSha: sha, readFrom: '.git/packed-refs' };
208		}
209		return null;
210	}
211	
212	/**
213	 * The lane layout the acquire stage writes: `<root>/.versionless/work/<id>/baseline`
214	 * for the tree, `<root>/evidence/ingests/<id>/source.json` for the journal.
215	 *
216	 * Reading the layout is how this stage finds the journal that belongs to a tree
217	 * it was handed. A source root that is not a lane baseline yields nothing here,
218	 * which leaves the revision unread rather than guessed at.
219	 */
220	export function acquisitionLaneOf(
221		sourceRoot: string,
222	): Readonly<{ workspaceRoot: string; laneId: string }> | null {
223		const segments = path.resolve(sourceRoot).split('/');
224		if (segments.length < 5) return null;
225		const [marker, work, laneId, baseline] = segments.slice(-4) as [string, string, string, string];
226		if (marker !== '.versionless' || work !== 'work' || baseline !== 'baseline') return null;
227		if (laneId === '') return null;
228		return Object.freeze({ workspaceRoot: segments.slice(0, -4).join('/'), laneId });
229	}
230	
231	/**
232	 * The acquisition journal for a tree, read from the pipeline's own evidence.
233	 *
234	 * `acquire` resolves the revision through a consented transaction, reconciles
235	 * the archive against the Git tree the repository publishes, and journals both
236	 * to `evidence/ingests/<id>/source.json`. This reads that journal — nothing is
237	 * fetched and no socket is opened — and returns it unjudged; the gates below
238	 * decide whether it is a reading of *this* tree.
239	 */
240	async function readAcquisitionJournal(
241		sourceRoot: string,
242		ingestId: string,
243	): Promise<Readonly<{ file: string; document: Record<string, unknown> }> | null> {
244		const lane = acquisitionLaneOf(sourceRoot);
245		if (lane === null) return null;
246		const seen = new Set<string>();
247		for (const candidate of [lane.laneId, ingestId]) {
248			if (candidate === '' || seen.has(candidate)) continue;
249			seen.add(candidate);
250			const relative = `evidence/ingests/${candidate}/source.json`;
251			const file = path.join(lane.workspaceRoot, relative);
252			if (!(await fileExists(file))) continue;
253			const document = await readJsonFile(file);
254			if (document === null) continue;
255			return Object.freeze({ file: relative, document });
256		}
257		return null;
258	}
259	
260	const stringAt = (document: Record<string, unknown>, ...keys: readonly string[]): string | null => {
261		let current: unknown = document;
262		for (const key of keys) {
263			if (current === null || typeof current !== 'object') return null;
264			current = (current as Record<string, unknown>)[key];
265		}
266		return typeof current === 'string' && current.trim() !== '' ? current.trim() : null;
267	};
268	
269	/**
270	 * The revision the acquisition journal pinned, or a named refusal.
271	 *
272	 * Four gates, and every one of them refuses rather than degrades. A journal
273	 * whose transaction did not bind a source is not a pin; a journal carrying no
274	 * consent identifier is not a consented reading; a journal carrying no parity
275	 * basis — the archive reconciled against the published Git tree, byte-identical
276	 * across two streams — states no relationship between the bytes and the commit;
277	 * and a journal whose manifest digest is not this tree's digest is a reading of
278	 * some other bytes.
279	 */
280	function revisionOfAcquisitionJournal(
281		file: string,
282		document: Record<string, unknown>,
283		tree: IngestTreeReading,
284	): Readonly<{ commitSha: string; readFrom: string }> {
285		const result = stringAt(document, 'result');
286		if (result !== 'source-bound')
287			refuse({
288				code: 'ingest.acquisition-journal-not-source-bound',
289				message: `Ingest: ${file} records the acquisition of this tree with result ${result ?? 'none'} rather than source-bound. Only a transaction that bound a source states a revision these bytes are pinned to, so this stage reads no pin out of it; declare the revision with --revision <commit-sha> if you know it by other means.`,
290				stage: 'ingest',
291				origin: 'pipeline',
292			});
293		const consentId = stringAt(document, 'consentId');
294		if (consentId === null)
295			refuse({
296				code: 'ingest.acquisition-journal-carries-no-consent',
297				message: `Ingest: ${file} names no consentId, so nothing in it says under whose consent the network was opened. A journal without consent is not a reading this stage adopts a pin from.`,
298				stage: 'ingest',
299				origin: 'pipeline',
300			});
301		const journalled = stringAt(document, 'archiveParity', 'normalizedManifestSha256');
302		const transaction = document.transaction as Record<string, unknown> | undefined;
303		const matchesGitTree = transaction?.archiveMatchesGitTree === true;
304		const byteIdentical = transaction?.archivesByteIdentical === true;
305		if (journalled === null || !matchesGitTree || !byteIdentical)
306			refuse({
307				code: 'ingest.acquisition-journal-carries-no-parity-basis',
308				message: `Ingest: ${file} carries no parity basis — archiveMatchesGitTree ${String(matchesGitTree)}, archivesByteIdentical ${String(byteIdentical)}, archive manifest ${journalled ?? 'unrecorded'}. A journal that did not reconcile its archive against the Git tree the repository publishes establishes no relationship between these bytes and the commit it names, so this stage reads no pin out of it.`,
309				stage: 'ingest',
310				origin: 'pipeline',
311			});
312		const commitSha = stringAt(document, 'revision', 'commitSha');
313		if (commitSha === null || !lowerHex40.test(commitSha))
314			refuse({
315				code: 'ingest.acquisition-journal-revision-unreadable',
316				message: `Ingest: ${file} records the revision ${commitSha ?? 'none'}, which is not a 40-character lower-case hexadecimal commit sha. The pin is what the licence reading and every later record are relative to, so an abbreviated or symbolic revision is refused rather than resolved into one.`,
317				stage: 'ingest',
318				origin: 'pipeline',
319			});
320		if (journalled !== tree.normalizedManifestSha256)
321			refuse({
322				code: 'ingest.acquisition-journal-does-not-match-the-tree',
323				message: `Ingest: ${file} journalled the manifest digest ${journalled} for the source it acquired, and the tree on disk walks to ${tree.normalizedManifestSha256}. These are not the same bytes, so the revision that journal names is not the revision this tree is sitting at; re-acquire the source, or declare the revision with --revision <commit-sha>.`,
324				stage: 'ingest',
325				origin: 'pipeline',
326			});
327		return Object.freeze({
328			commitSha,
329			readFrom: `${file} (consent ${consentId}; result source-bound; archive reconciled against the published Git tree and byte-identical across two streams; journalled manifest ${journalled} is the digest this stage walked)`,
330		});
331	}
332	
333	/**
334	 * The one immediate subdirectory carrying a manifest, or `null`.
335	 *
336	 * Zero and more than one are both refusals upstream. "Pick the first" is
337	 * exactly the kind of default this stage exists to not take.
338	 */
339	async function manifestBearingSubdirectories(sourceRoot: string): Promise<readonly string[]> {
340		const found: string[] = [];
341		let entries: string[];
342		try {
343			entries = (await readdir(sourceRoot, { withFileTypes: true }))
344				.filter((entry) => entry.isDirectory())
345				.map((entry) => entry.name)
346				.sort();
347		} catch {
348			return Object.freeze([]);
349		}
350		for (const name of entries) {
351			if (name === 'node_modules' || name === '.git') continue;
352			if (await fileExists(path.join(sourceRoot, name, 'package.json'))) found.push(name);
353		}
354		return Object.freeze(found);
355	}
356	
357	async function readTree(sourceRoot: string): Promise<IngestTreeReading> {
358		const relatives = await workspacePathsBelow(sourceRoot, sourceRoot);
359		const files: ExtractedFile[] = [];
360		let bytes = 0;
361		for (const relative of relatives) {
362			const contents = await readFile(path.join(sourceRoot, relative));
363			bytes += contents.byteLength;
364			files.push({ path: relative, bytes: contents });
365		}
366		return Object.freeze({
367			files: files.length,
368			bytes,
369			normalizedManifestSha256: normalizedManifest(files).sha256,
370		});
371	}
372	
373	/**
374	 * Admit an application source, or refuse by name.
375	 *
376	 * Nothing is written and nothing is fetched. What comes back is the record —
377	 * the same shape the per-application modules publish under `evidence/ingests/`,
378	 * derived rather than authored.
379	 */
380	export async function ingestApplicationSource(
381		sourceRoot: string,
382		declarations: IngestDeclarations = DEFAULT_INGEST_DECLARATIONS,
383	): Promise<IngestRecord> {
384		if (!(await directoryExists(sourceRoot)))
385			refuse({
386				code: 'ingest.source-root-not-a-directory',
387				message: `Ingest: the application source ${sourceRoot} is not a directory. This stage reads a source that is already on disk; it does not acquire one.`,
388				stage: 'ingest',
389				origin: 'pipeline',
390			});
391	
392		const declaredFrontend = declarations.frontendRoot;
393		let frontendRoot: string;
394		let frontendRootSource: ValueSource;
395		if (declaredFrontend !== null) {
396			frontendRoot = declaredFrontend;
397			frontendRootSource = 'declared';
398			if (!(await fileExists(path.join(sourceRoot, frontendRoot, 'package.json'))))
399				refuse({
400					code: 'ingest.declared-frontend-root-carries-no-manifest',
401					message: `Ingest: --frontend-root ${frontendRoot} was declared and that directory carries no package.json. The frontend root is where the application's own manifest lives; this stage does not look elsewhere for it.`,
402					stage: 'ingest',
403					origin: 'pipeline',
404				});
405		} else if (await fileExists(path.join(sourceRoot, 'package.json'))) {
406			frontendRoot = '.';
407			frontendRootSource = 'read';
408		} else {
409			const candidates = await manifestBearingSubdirectories(sourceRoot);
410			if (candidates.length === 0)
411				refuse({
412					code: 'ingest.frontend-root-not-found',
413					message: `Ingest: neither ${sourceRoot} nor any of its immediate subdirectories carries a package.json, so this stage found no frontend to admit. Declare the directory with --frontend-root <dir> if the manifest sits deeper than one level.`,
414					stage: 'ingest',
415					origin: 'pipeline',
416				});
417			if (candidates.length > 1)
418				refuse({
419					code: 'ingest.frontend-root-ambiguous',
420					message: `Ingest: ${String(candidates.length)} immediate subdirectories carry a package.json (${candidates.join(', ')}), so which one is the application is not something this stage reads. Declare it with --frontend-root <dir>.`,
421					stage: 'ingest',
422					origin: 'pipeline',
423				});
424			frontendRoot = candidates[0] as string;
425			frontendRootSource = 'read';
426		}
427		const frontendDirectory = path.join(sourceRoot, frontendRoot);
428		const manifestFile = path.join(frontendDirectory, 'package.json');
429	
430		const manifest = await readJsonFile(manifestFile);
431		if (manifest === null)
432			refuse({
433				code: 'ingest.frontend-manifest-unreadable',
434				message: `Ingest: ${path.join(frontendRoot, 'package.json')} is not readable as a JSON object, so nothing about this application's identity or its declared dependencies can be read from it.`,
435				stage: 'ingest',
436				origin: 'pipeline',
437			});
438	
439		let id: string;
440		let idSource: ValueSource;
441		if (declarations.id !== null) {
442			id = declarations.id;
443			idSource = 'declared';
444		} else if (typeof manifest.name === 'string' && manifest.name.trim() !== '') {
445			id = manifest.name.trim();
446			idSource = 'read';
447		} else {
448			refuse({
449				code: 'ingest.identifier-not-determined',
450				message: `Ingest: ${path.join(frontendRoot, 'package.json')} declares no name, so this application has no identity this stage read. The directory it happens to sit in is not an identity, and this flow does not use one as a substitute; declare it with --id <identifier>.`,
451				stage: 'ingest',
452				origin: 'pipeline',
453			});
454		}
455	
456		const tree = await readTree(sourceRoot);
457	
458		let commitSha: string;
459		let commitShaSource: ValueSource;
460		let commitShaReadFrom: string | null = null;
461		if (declarations.revision !== null) {
462			commitSha = declarations.revision;
463			commitShaSource = 'declared';
464			if (!lowerHex40.test(commitSha))
465				refuse({
466					code: 'ingest.declared-revision-is-not-a-commit-sha',
467					message: `Ingest: --revision ${commitSha} is not a 40-character lower-case hexadecimal commit sha. The pin is what the licence reading and every later record are relative to, so an abbreviated or symbolic revision is refused rather than resolved into one.`,
468					stage: 'ingest',
469					origin: 'pipeline',
470				});
471		} else {
472			/**
473			 * A checkout states its own revision. A tree the acquire stage fetched
474			 * carries no Git metadata at all — the archive it reconciled has none —
475			 * and the revision it was fetched at is in this pipeline's own journal,
476			 * written under consent and gated on parity. Reading that journal is
477			 * offline and it is a reading, not a declaration: without it every
478			 * acquired application refuses here and an operator supplies the sha by
479			 * hand, which is the manual step this flow exists to not have.
480			 */
481			let read = await readGitRevision(sourceRoot);
482			if (read === null) {
483				const journal = await readAcquisitionJournal(sourceRoot, id);
484				if (journal !== null)
485					read = revisionOfAcquisitionJournal(journal.file, journal.document, tree);
486			}
487			if (read === null)
488				refuse({
489					code: 'ingest.revision-not-determined',
490					message: `Ingest: ${sourceRoot} carries no readable Git metadata and no acquisition journal of this pipeline's own names it, so the revision this source is pinned to is not something this stage read. An unpinned source has no revision for the licence reading or any later record to be relative to; declare it with --revision <commit-sha>.`,
491					stage: 'ingest',
492					origin: 'pipeline',
493				});
494			commitSha = read.commitSha;
495			commitShaSource = 'read';
496			commitShaReadFrom = read.readFrom;
497		}
498	
499		const licence = await readLicenceAtPin(sourceRoot, manifestFile, declarations.licence);
500	
501		let lockfile: string | null = null;
502		let closureReason: string | null = null;
503		if (declarations.lockfile !== null) {
504			lockfile = declarations.lockfile;
505			if (!(await fileExists(path.join(frontendDirectory, lockfile))))
506				refuse({
507					code: 'ingest.declared-lockfile-absent',
508					message: `Ingest: --lockfile ${lockfile} was declared and ${path.join(frontendRoot, lockfile)} does not exist. This stage reads the closure the declared lockfile pins; it does not fall back to another one.`,
509					stage: 'ingest',
510					origin: 'pipeline',
511				});
512		} else {
513			for (const name of CLOSURE_LOCKFILES)
514				if (lockfile === null && (await fileExists(path.join(frontendDirectory, name))))
515					lockfile = name;
516			if (lockfile === null) {
517				const foreign: string[] = [];
518				for (const name of Object.keys(FOREIGN_CLOSURE_LOCKFILES).sort())
519					if (await fileExists(path.join(frontendDirectory, name))) foreign.push(name);
520				closureReason =
521					foreign.length > 0
522						? `the frontend root carries ${foreign.join(', ')}, whose closure is pinned by ${foreign.map((name) => FOREIGN_CLOSURE_LOCKFILES[name] ?? 'another package manager').join(', ')}. This reading is of an npm lockfile and this flow does not translate it onto another package manager's format.`
523						: `the frontend root carries none of ${CLOSURE_LOCKFILES.join(', ')}, so there is no recorded closure to read. The application's declared dependency ranges are in the detection above; what they resolve to is not established by this record.`;
524			}
525		}
526	
527		let closure: LegacyClosureRecord | null = null;
528		if (lockfile !== null) {
529			const packageBytes = await readFile(manifestFile);
530			const lockBytes = await readFile(path.join(frontendDirectory, lockfile));
531			try {
532				closure = analyzeLegacyLockClosure(
533					{ id, frontendRoot, lockFileName: lockfile },
534					{ verifiedSourceRoot: frontendRoot, packageBytes, lockBytes },
535				);
536			} catch (error) {
537				refuse({
538					code: 'ingest.lockfile-closure-unreadable',
539					message: `Ingest: ${path.join(frontendRoot, lockfile)} could not be read as a dependency closure — ${error instanceof Error ? error.message : String(error)}. A lockfile whose shape this reading does not recognise is refused rather than recorded as a closure it is not.`,
540					stage: 'ingest',
541					origin: 'pipeline',
542				});
543			}
544		}
545	
546		return Object.freeze({
547			stage: 'ingest',
548			schemaVersion: INGEST_RECORD_SCHEMA,
549			ran: true,
550			reason: null,
551			id,
552			idSource,
553			frontendRoot,
554			frontendRootSource,
555			pin: Object.freeze({
556				repository: declarations.repository,
557				ref: declarations.ref,
558				commitSha,
559				commitShaSource,
560				commitShaReadFrom,
561			}),
562			tree,
563			detected: await analyzeApplication(frontendDirectory),
564			licence,
565			closure,
566			closureReason,
567			notEstablished: INGEST_NOT_ESTABLISHED,
568		});
569	}
570	
571	/** The ingest record as an operator reads it. */
572	export function renderIngest(record: IngestRecord): string {
573		if (!record.ran) return `ingest: not run — ${record.reason ?? ''}\n`;
574		const lines = [
575			`application: ${record.id ?? ''} (${record.idSource ?? ''})`,
576			`frontend root: ${record.frontendRoot ?? ''} (${record.frontendRootSource ?? ''})`,
577			`pinned revision: ${record.pin?.commitSha ?? ''} (${record.pin?.commitShaSource ?? ''}${
578				record.pin?.commitShaReadFrom === null || record.pin?.commitShaReadFrom === undefined
579					? ''
580					: ` from ${record.pin.commitShaReadFrom}`
581			})`,
582			`repository: ${record.pin?.repository ?? 'not declared'}; ref: ${record.pin?.ref ?? 'not declared'}`,
583			`tree: ${String(record.tree?.files ?? 0)} file(s), ${String(record.tree?.bytes ?? 0)} byte(s), manifest ${(record.tree?.normalizedManifestSha256 ?? '').slice(0, 12)}`,
584			`lineage: ${record.detected?.lineage ?? ''}; builder: ${record.detected?.builder ?? ''}; node era: ${record.detected?.nodeEra.declared ?? ''}`,
585			`licence: ${record.licence?.identifier ?? ''} (${record.licence?.identifierSource ?? ''})`,
586			record.closure === null
587				? `closure: none — ${record.closureReason ?? ''}`
588				: `closure: ${record.closure.lockState.file} — ${String(record.closure.counts.lockedPlacements)} placement(s), ${String(record.closure.counts.distinctNameVersionPairs)} distinct name@version`,
589			'',
590		];
591		for (const line of [...record.notEstablished, ...(record.licence?.notEstablished ?? [])])
592			lines.push(`not established: ${line}`);
593		return `${lines.join('\n')}\n`;
594	}
