38	import { homedir } from 'node:os';
39	import * as path from 'pathe';
40	import {
41		ANGULAR_TARGET_CELLS,
42		type AngularTargetCell,
43	} from '../../../frameworks/angular/src/index.ts';
44	import {
45		analyzeApplication,
46		declaredDependencies,
47		directoryExists,
48		fileExists,
49		readJsonFile,
50		UNKNOWN,
51		type ApplicationAnalysis,
52		type Lineage,
53	} from './analyze.ts';
54	import { refuse, type PipelineRefusal } from './refusals.ts';
