67	/**
68	 * A toolchain cell this stage can name, with the Node line it declares.
69	 *
70	 * Every entry either restates a cell a frozen adapter publishes — the `id` and
71	 * the `nodeLine` are read from the adapter's own declaration, never retyped —
72	 * or is described from a measurement in `evidence/`, and says which.
73	 */
74	export type DescribedCell = Readonly<{
75		id: string;
76		lineage: Lineage;
77		/** The Node line the cell declares, verbatim. */
78		nodeLine: string;
79		nodeMajor: number;
80		/** Where this description comes from. */
81		describedBy: string;
82		/** Whether an adapter in this repository publishes the cell as a target. */
83		published: boolean;
84		/** What establishing this cell provides here, and what it does not. */
85		provides: string;
86	}>;
87	
88	/** The leading major of a version or range, or `null` when it reads as none. */
89	export function leadingMajor(value: string): number | null {
90		let digits = '';
91		let started = false;
92		for (const character of value.trim()) {
93			const code = character.charCodeAt(0);
94			const isDigit = code >= 48 && code <= 57;
95			if (isDigit) {
96				started = true;
97				digits += character;
98				continue;
99			}
100			if (started) break;
101			if (character === '^' || character === '~' || character === 'v' || character === '=')
102				continue;
103			if (character === '>' || character === '<' || character === ' ') continue;
104			return null;
105		}
106		return digits === '' ? null : Number.parseInt(digits, 10);
107	}
108	
109	function cellOfAdapterCell(cell: AngularTargetCell): DescribedCell | null {
110		const major = leadingMajor(cell.nodeLine);
111		if (major === null) return null;
112		return Object.freeze({
113			id: cell.id,
114			lineage: 'angular' as const,
115			nodeLine: cell.nodeLine,
116			nodeMajor: major,
117			describedBy: `published by the frozen Angular adapter as an AngularTargetCell; the Node line is the cell's own nodeLine declaration.`,
118			published: true,
119			provides:
120				'the Node runtime the cell declares. The Angular packages the cell aligns a manifest to are written by the plan stage and resolved by the install stage, not by this one.',
121		});
122	}
