136		lineage: 'angular' as const,
137		nodeLine: '16.20.2',
138		nodeMajor: 16,
139		describedBy:
140			'described by evidence/spikes/ngcc-1213-feasibility/verdict.json, which names angular-13.4.0 the honest cell — @angular/compiler-cli 13.4.0 still ships a real ngcc bin and back-compiles the pre-Ivy libraries, and the cell Node runtime it recorded is v16.20.2. No adapter in this repository publishes this cell as a migration target.',
141		published: false,
142		provides:
143			'the Node runtime the cell declares. The Angular 13 toolchain itself, and the rxjs 6 pin the spike recorded as its price, are not installed or written by this stage.',
144	});
