146	/** Every cell this stage can name, adapter-published ones first. */
147	export const DESCRIBED_CELLS: readonly DescribedCell[] = Object.freeze([
148		...ANGULAR_TARGET_CELLS.map(cellOfAdapterCell).filter(
149			(cell): cell is DescribedCell => cell !== null,
150		),
151		NGCC_ANGULAR_13_CELL,
152	]);
