158	/**
159	 * Packages this repository measured as publishing no binding for an
160	 * architecture, with the reading verbatim from the measurement.
161	 *
162	 * This is a list rather than a name so the reading is of the closure, not of
163	 * one package: the lockfile and the manifest are read for every entry. A native
164	 * dependency nobody here measured is not in this table and is not counted,
165	 * which the record states rather than implying the closure was cleared.
166	 */
167	export type ArchitectureBinding = Readonly<{
168		package: string;
169		/** The highest major with no binding for the host architecture named below. */
170		throughMajor: number;
171		/** The architecture a closure carrying this package requires instead. */
172		requiresArchitecture: string;
173		/** The architecture the package publishes no binding for. */
174		noBindingFor: string;
175		fact: string;
176	}>;
177	
178	export const ARCHITECTURE_BINDINGS: readonly ArchitectureBinding[] = Object.freeze([
179		Object.freeze({
180			package: 'node-sass',
181			throughMajor: 4,
182			requiresArchitecture: 'x64',
183			noBindingFor: 'arm64',
184			fact: 'node-sass 4.12.0 refuses the host outright: OS X Unsupported architecture (arm64) with Unsupported runtime (137). node-sass 4.x publishes no arm64 binding for a modern Node ABI (evidence/spikes/thin-wrapper-cost/verdict.json, finding C2).',
185		}),
186	]);
187	
188	export type ArchitectureRequirement = Readonly<{
189		package: string;
190		/** The version or range that was read, verbatim. */
191		version: string;
192		/** Where the version was read: a lockfile, or the manifest's declaration. */
193		readFrom: string;
194		requiresArchitecture: string;
195		noBindingFor: string;
196		fact: string;
197	}>;
198	
199	/** A clause quoted into a longer message, ended once rather than twice. */
200	const sentence = (value: string): string => (value.endsWith('.') ? value : `${value}.`);
201	
202	/** Whether a binding entry bites at the version that was read. */
203	function bindingApplies(binding: ArchitectureBinding, version: string): boolean {
204		const major = leadingMajor(version);
205		/**
206		 * A version this stage cannot read is treated as bitten. The refusing
207		 * direction is the honest one: the alternative is proceeding into the wall
208		 * the spike already measured and calling it an unread version.
209		 */
210		return major === null || major <= binding.throughMajor;
211	}
212	
213	function collectLockfilePackages(
214		document: Record<string, unknown>,
215		into: Map<string, string>,
216	): void {
217		const packages = document.packages as Record<string, unknown> | undefined;
218		if (packages !== undefined && packages !== null)
219			for (const key of Object.keys(packages).sort()) {
220				const entry = packages[key] as Record<string, unknown> | undefined;
221				if (entry === undefined || entry === null) continue;
222				const marker = 'node_modules/';
223				const index = key.lastIndexOf(marker);
224				if (index < 0) continue;
225				const name = key.slice(index + marker.length);
226				const version = typeof entry.version === 'string' ? entry.version : UNKNOWN;
227				if (!into.has(name)) into.set(name, version);
228			}
229		const walk = (tree: Record<string, unknown> | undefined): void => {
230			if (tree === undefined || tree === null) return;
231			for (const name of Object.keys(tree).sort()) {
232				const entry = tree[name] as Record<string, unknown> | undefined;
233				if (entry === undefined || entry === null) continue;
234				const version = typeof entry.version === 'string' ? entry.version : UNKNOWN;
235				if (!into.has(name)) into.set(name, version);
236				walk(entry.dependencies as Record<string, unknown> | undefined);
237			}
238		};
239		walk(document.dependencies as Record<string, unknown> | undefined);
240	}
241	
242	/**
243	 * The architecture requirements the application's own closure carries.
244	 *
245	 * The lockfile is read first, because it states resolved versions; the
246	 * manifest's declared range is read for a tree that pins no closure. Both
247	 * readings are recorded with the file they came from, so a reader can tell a
248	 * resolved version from a declared range.
249	 */
250	export async function readArchitectureRequirements(
251		frontendDirectory: string,
252	): Promise<readonly ArchitectureRequirement[]> {
253		const locked = new Map<string, string>();
254		let lockfileRead: string | null = null;
255		for (const name of ERA_CELL_LOCKFILES) {
256			if (lockfileRead !== null) continue;
257			const file = path.join(frontendDirectory, name);
258			if (!(await fileExists(file))) continue;
259			const document = await readJsonFile(file);
260			if (document === null) continue;
261			lockfileRead = name;
262			collectLockfilePackages(document, locked);
263		}
264		const declared = declaredDependencies(
265			await readJsonFile(path.join(frontendDirectory, 'package.json')),
266		);
267		const requirements: ArchitectureRequirement[] = [];
268		for (const binding of ARCHITECTURE_BINDINGS) {
269			const lockedVersion = locked.get(binding.package);
270			const declaredRange = declared[binding.package];
271			const version = lockedVersion ?? declaredRange;
272			if (version === undefined) continue;
273			if (!bindingApplies(binding, version)) continue;
274			requirements.push(
275				Object.freeze({
276					package: binding.package,
277					version,
278					readFrom:
279						lockedVersion === undefined
280							? 'package.json'
281							: (lockfileRead ?? (ERA_CELL_LOCKFILES[0] as string)),
282					requiresArchitecture: binding.requiresArchitecture,
283					noBindingFor: binding.noBindingFor,
284					fact: binding.fact,
285				}),
286			);
287		}
288		return Object.freeze(
289			requirements.sort((left, right) => (left.package < right.package ? -1 : 1)),
290		);
291	}
292	
293	type Clause = Readonly<{ operator: string; major: number; minorIsZeroOrAbsent: boolean }>;
294	
295	const CLAUSE_PATTERN =
296		/(>=|<=|>|<|\^|~|=)?\s*v?(\d+)(?:\.(\d+|x|X|\*))?(?:\.(\d+|x|X|\*))?(?:[-+][0-9A-Za-z.-]+)?/g;
297	
298	const withoutSeparators = (value: string): string =>
299		[...value]
300			.filter((character) => character !== ' ' && character !== '\t' && character !== ',')
301			.join('');
302	
303	function clausesOf(alternative: string): readonly Clause[] | null {
304		const matches = [...alternative.matchAll(CLAUSE_PATTERN)];
305		if (matches.length === 0) return null;
306		/**
307		 * Everything in the alternative has to be a clause this reading consumed. A
308		 * declaration carrying a word — `lts/gallium`, `current` — leaves residue
309		 * here and is reported as unreadable rather than having its digits mined
310		 * out of it.
311		 */
312		if (
313			withoutSeparators(matches.map((match) => match[0]).join('')) !==
314			withoutSeparators(alternative)
315		)
316			return null;
317		const clauses: Clause[] = [];
318		for (const match of matches) {
319			const major = Number.parseInt(match[2] as string, 10);
320			const minor = match[3];
321			clauses.push({
322				operator: match[1] ?? '',
323				major,
324				minorIsZeroOrAbsent: minor === undefined || minor === '0',
325			});
326		}
327		return Object.freeze(clauses);
328	}
329	
330	/**
331	 * The Node majors a declaration names, or `null` when it names none this stage
332	 * reads.
333	 *
334	 * An open-ended lower bound (`>=16.10.0`) names every major from 16 upwards and
335	 * is not a reading; a two-sided range names the majors between its bounds; a
336	 * pinned, caret or tilde clause names one. A declaration naming more than one
337	 * major is a declaration this stage will not pick from.
338	 */
339	export function nodeMajorsOfDeclaration(declared: string): readonly number[] | null {
340		const trimmed = declared.trim();
341		if (trimmed === '' || trimmed === UNKNOWN) return null;
342		const majors = new Set<number>();
343		for (const alternative of trimmed.split('||')) {
344			const clauses = clausesOf(alternative);
345			if (clauses === null) return null;
346			const pins: number[] = [];
347			let low: number | null = null;
348			let high: number | null = null;
349			for (const clause of clauses) {
350				if (clause.operator === '>=' || clause.operator === '>')
351					low = low === null ? clause.major : Math.max(low, clause.major);
352				else if (clause.operator === '<') {
353					const bound = clause.minorIsZeroOrAbsent ? clause.major - 1 : clause.major;
354					high = high === null ? bound : Math.min(high, bound);
355				} else if (clause.operator === '<=')
356					high = high === null ? clause.major : Math.min(high, clause.major);
357				else pins.push(clause.major);
358			}
359			if (pins.length > 0) for (const pin of pins) majors.add(pin);
360			else if (low !== null && high !== null) {
361				if (high < low) return null;
362				for (let major = low; major <= high; major += 1) majors.add(major);
363			} else return null;
364		}
365		return Object.freeze([...majors].sort((left, right) => left - right));
366	}
367	
368	/**
369	 * One place a tree states which Node line it was built on, read verbatim.
370	 *
371	 * `majors` is `null` when the text carries no numeric major line this stage
372	 * reads — `latest`, `lts`, `current`, `lts/gallium`, `latest-browsers`, a CI
373	 * expression — which is residue rather than a cell. More than one major is a
374	 * source this stage will not pick from. Every source consulted is recorded,
375	 * winner or not, because which readings were available and what each said is
376	 * the part a reader cannot reconstruct from the answer.
377	 */
378	export type NodeMajorSourceReading = Readonly<{
379		/** The file and key the reading came out of. */
380		source: string;
381		/** What that file literally says there. */
382		text: string;
383		majors: readonly number[] | null;
384	}>;
385	
386	/** The workflow keys a CI file names its Node line under. */
387	const WORKFLOW_NODE_KEYS: readonly string[] = Object.freeze(['node-version', 'node_version']);
388	
389	const stripComment = (value: string): string => {
390		const hash = value.indexOf(' #');
391		return (hash < 0 ? value : value.slice(0, hash)).trim();
392	};
393	
394	const unquoted = (value: string): string => {
395		const trimmed = value.trim();
396		if (trimmed.length >= 2 && (trimmed.startsWith("'") || trimmed.startsWith('"')))
397			return trimmed.slice(1, -1);
398		return trimmed;
399	};
400	
401	/**
402	 * The majors a list of declarations names between them, or `null`.
403	 *
404	 * A list carrying an element this stage cannot read is unreadable as a whole:
405	 * reading the rest of it would be reading part of a declaration and calling it
406	 * the declaration.
407	 */
408	function majorsOfList(values: readonly string[]): readonly number[] | null {
409		const majors = new Set<number>();
410		for (const value of values) {
411			const read = nodeMajorsOfDeclaration(value);
412			if (read === null) return null;
413			for (const major of read) majors.add(major);
414		}
415		return majors.size === 0
416			? null
417			: Object.freeze([...majors].sort((left, right) => left - right));
418	}
419	
420	/** `[12.x, 14.x]` read as its elements, or the value as a single element. */
421	function declarationElements(value: string): readonly string[] {
422		const trimmed = stripComment(value);
423		if (trimmed.startsWith('[') && trimmed.endsWith(']'))
424			return Object.freeze(
425				trimmed
426					.slice(1, -1)
427					.split(',')
428					.map((element) => unquoted(element))
429					.filter((element) => element !== ''),
430			);
431		const single = unquoted(trimmed);
432		return single === '' ? Object.freeze([]) : Object.freeze([single]);
433	}
434	
435	async function readWorkflowNodeSources(root: string): Promise<NodeMajorSourceReading[]> {
436		const directory = path.join(root, '.github', 'workflows');
437		if (!(await directoryExists(directory))) return [];
438		const readings: NodeMajorSourceReading[] = [];
439		for (const name of await entriesOfAnyKind(directory)) {
440			if (!name.endsWith('.yml') && !name.endsWith('.yaml')) continue;
441			const file = path.join(directory, name);
442			if (!(await fileExists(file))) continue;
443			const lines = (await readFile(file, 'utf8')).split('\n');
444			for (let index = 0; index < lines.length; index += 1) {
445				const line = lines[index] as string;
446				const match = /^(\s*)(?:-\s+)?(node[-_]version)\s*:(.*)$/.exec(line);
447				if (match === null) continue;
448				const key = match[2] as string;
449				if (!WORKFLOW_NODE_KEYS.includes(key)) continue;
450				let text = stripComment(match[3] as string);
451				let elements = declarationElements(match[3] as string);
452				if (elements.length === 0) {
453					/** A block sequence: the values are the `- item` lines below it. */
454					const items: string[] = [];
455					for (let ahead = index + 1; ahead < lines.length; ahead += 1) {
456						const item = /^\s*-\s+(.*)$/.exec(lines[ahead] as string);
457						if (item === null) break;
458						items.push(unquoted(stripComment(item[1] as string)));
459					}
460					if (items.length === 0) continue;
461					elements = Object.freeze(items);
462					text = `[${items.join(', ')}]`;
463				}
464				readings.push(
465					Object.freeze({
466						source: `.github/workflows/${name}#${key}`,
467						text,
468						majors: majorsOfList(elements),
469					}),
470				);
471			}
472		}
473		return readings;
474	}
475	
476	async function entriesOfAnyKind(directory: string): Promise<readonly string[]> {
477		try {
478			return (await readdir(directory, { withFileTypes: true }))
479				.map((entry) => entry.name)
480				.sort();
481		} catch {
482			return Object.freeze([]);
483		}
484	}
485	
486	async function readDockerfileNodeSources(root: string): Promise<NodeMajorSourceReading[]> {
487		const readings: NodeMajorSourceReading[] = [];
488		for (const name of await entriesOfAnyKind(root)) {
489			if (!name.startsWith('Dockerfile')) continue;
490			const file = path.join(root, name);
491			if (!(await fileExists(file))) continue;
492			const lines = (await readFile(file, 'utf8')).split('\n');
493			for (let index = 0; index < lines.length; index += 1) {
494				const match = /^\s*FROM\s+(\S+)/i.exec(lines[index] as string);
495				if (match === null) continue;
496				const image = match[1] as string;
497				const colon = image.lastIndexOf(':');
498				if (colon < 0) continue;
499				const repository = image.slice(0, colon);
500				const slash = repository.lastIndexOf('/');
501				if (repository.slice(slash + 1) !== 'node') continue;
502				readings.push(
503					Object.freeze({
504						source: `${name}#FROM line ${String(index + 1)}`,
505						text: image,
506						majors: nodeMajorsOfDeclaration(image.slice(colon + 1)),
507					}),
508				);
509			}
510		}
511		return readings;
512	}
513	
514	/**
515	 * Every place this tree states a Node line, in the precedence the honesty
516	 * ruling fixed: the tree's own version-manager files, then the toolchain
517	 * pins, then the images and workflows its authors actually ran, and the
518	 * manifest's `engines` range last because it is a compatibility bound rather
519	 * than a statement of what was run.
520	 *
521	 * Nothing here picks. Every source is returned with what it literally says.
522	 */
523	export async function readNodeMajorSources(
524		root: string,
525	): Promise<readonly NodeMajorSourceReading[]> {
526		const readings: NodeMajorSourceReading[] = [];
527		for (const name of ['.nvmrc', '.node-version']) {
528			const file = path.join(root, name);
529			if (!(await fileExists(file))) continue;
530			const text = (await readFile(file, 'utf8')).trim();
531			if (text === '') continue;
532			readings.push(Object.freeze({ source: name, text, majors: nodeMajorsOfDeclaration(text) }));
533		}
534		const manifest = await readJsonFile(path.join(root, 'package.json'));
535		const volta = manifest?.volta as Record<string, unknown> | undefined;
536		if (volta !== undefined && volta !== null && typeof volta.node === 'string') {
537			const text = volta.node.trim();
538			if (text !== '')
539				readings.push(
540					Object.freeze({
541						source: 'package.json#volta.node',
542						text,
543						majors: nodeMajorsOfDeclaration(text),
544					}),
545				);
546		}
547		const toolVersions = path.join(root, '.tool-versions');
548		if (await fileExists(toolVersions))
549			for (const line of (await readFile(toolVersions, 'utf8')).split('\n')) {
550				const match = /^nodejs\s+(\S+)/.exec(line.trim());
551				if (match === null) continue;
552				const text = match[1] as string;
553				readings.push(
554					Object.freeze({
555						source: '.tool-versions#nodejs',
556						text,
557						majors: nodeMajorsOfDeclaration(text),
558					}),
559				);
560			}
561		readings.push(...(await readDockerfileNodeSources(root)));
