634	const VERSION_MANAGERS: readonly VersionManager[] = Object.freeze([
635		Object.freeze({
636			supplier: 'fnm',
637			environmentVariable: 'FNM_DIR',
638			homeRoots: Object.freeze(['.local/share/fnm', 'Library/Application Support/fnm', '.fnm']),
639			versions: 'node-versions',
640			bin: 'installation/bin',
641		}),
