658	/** `node-v16.20.2-darwin-arm64` read as its three parts, or `null`. */
659	export function runtimeDirectoryName(
660		name: string,
661	): Readonly<{ version: string; platform: string; architecture: string }> | null {
662		if (!name.startsWith('node-v')) return null;
663		const parts = name.slice('node-'.length).split('-');
664		if (parts.length !== 3) return null;
665		const [version, platform, architecture] = parts as [string, string, string];
666		if (leadingMajor(version) === null) return null;
667		return Object.freeze({ version, platform, architecture });
668	}
