670	const normalizedVersion = (name: string): string => (name.startsWith('v') ? name : `v${name}`);
671	
672	async function entriesOf(directory: string): Promise<readonly string[]> {
673		try {
674			return (await readdir(directory, { withFileTypes: true }))
675				.filter((entry) => entry.isDirectory() || entry.isSymbolicLink())
676				.map((entry) => entry.name)
677				.sort();
678		} catch {
679			return Object.freeze([]);
680		}
681	}
