683	async function readWorkspaceRuntimes(workspaceRoot: string): Promise<InstalledRuntime[]> {
684		const cache = path.join(workspaceRoot, WORKSPACE_RUNTIME_CACHE);
685		if (!(await directoryExists(cache))) return [];
686		const runtimes: InstalledRuntime[] = [];
687		for (const entry of await entriesOf(cache))
688			for (const candidate of await entriesOf(path.join(cache, entry))) {
689				const read = runtimeDirectoryName(candidate);
690				if (read === null) continue;
691				if (!(await fileExists(path.join(cache, entry, candidate, 'bin', 'node')))) continue;
692				const major = leadingMajor(read.version);
693				if (major === null) continue;
694				runtimes.push(
695					Object.freeze({
696						version: normalizedVersion(read.version),
697						major,
698						platform: read.platform,
699						architecture: read.architecture,
700						supplier: WORKSPACE_RUNTIME_SUPPLIER,
701						location: `${WORKSPACE_RUNTIME_CACHE}/${entry}/${candidate}`,
702					}),
703				);
704			}
705		return runtimes;
706	}
