708	async function readVersionManagerRuntimes(
709		manager: VersionManager,
710		environment: NodeJS.ProcessEnv,
711		home: string,
712		platform: string,
713		architecture: string,
714	): Promise<{ present: boolean; runtimes: InstalledRuntime[] }> {
715		const declaredRoot = environment[manager.environmentVariable];
716		const roots = [
717			...(declaredRoot === undefined || declaredRoot === '' ? [] : [declaredRoot]),
718			...manager.homeRoots.map((relative) => path.join(home, relative)),
719		];
720		for (const root of roots) {
721			if (!(await directoryExists(root))) continue;
722			const versionsDirectory = path.join(root, manager.versions);
723			const runtimes: InstalledRuntime[] = [];
724			for (const entry of await entriesOf(versionsDirectory)) {
725				const major = leadingMajor(entry);
726				if (major === null) continue;
727				if (!(await fileExists(path.join(versionsDirectory, entry, manager.bin, 'node'))))
728					continue;
729				runtimes.push(
730					Object.freeze({
731						version: normalizedVersion(entry),
732						major,
733						/**
734						 * A version manager installs for the host it runs on, so the
735						 * platform and architecture are the host's. This stage read a
736						 * directory, not a binary header.
737						 */
738						platform,
739						architecture,
740						supplier: manager.supplier,
741						location: `${manager.versions}/${entry}`,
742					}),
743				);
744			}
745			return { present: true, runtimes };
746		}
747		return { present: false, runtimes: [] };
748	}
