750	const SUPPLIER_ORDER: readonly string[] = Object.freeze([
751		WORKSPACE_RUNTIME_SUPPLIER,
752		'fnm',
753		'nvm',
754		'volta',
755		RUNNING_PROCESS,
756	]);
757	
758	function compareRuntimes(left: InstalledRuntime, right: InstalledRuntime): number {
759		const leftOrder = SUPPLIER_ORDER.indexOf(left.supplier);
760		const rightOrder = SUPPLIER_ORDER.indexOf(right.supplier);
761		if (leftOrder !== rightOrder) return leftOrder - rightOrder;
762		if (left.version !== right.version) return left.version < right.version ? 1 : -1;
763		return left.location < right.location ? -1 : 1;
764	}
