766	/**
767	 * Read what this host can supply, without opening a socket and without running
768	 * another program.
769	 *
770	 * Every source is a directory this function reads: the process it runs in, the
771	 * runtimes the workspace already materialised under its own cache, and the
772	 * installed-version directories of the version managers it knows the layout of.
773	 * A runtime installed somewhere none of those reach is reported as absent,
774	 * which the record states rather than implying the host was enumerated.
775	 */
776	export async function readHostCell(
777		workspaceRoot = '.',
778		environment: NodeJS.ProcessEnv = process.env,
779		platform: string = process.platform,
780		architecture: string = process.arch,
781		runningVersion: string = process.version,
782	): Promise<HostCellReading> {
783		const runningMajor = leadingMajor(runningVersion) ?? 0;
784		const suppliers: string[] = [RUNNING_PROCESS];
785		const installed: InstalledRuntime[] = [
786			Object.freeze({
787				version: runningVersion,
788				major: runningMajor,
789				platform,
790				architecture,
791				supplier: RUNNING_PROCESS,
792				location: 'the process this stage is running in',
793			}),
794		];
795		const workspaceRuntimes = await readWorkspaceRuntimes(workspaceRoot);
796		if (await directoryExists(path.join(workspaceRoot, WORKSPACE_RUNTIME_CACHE)))
797			suppliers.push(WORKSPACE_RUNTIME_SUPPLIER);
798		installed.push(...workspaceRuntimes);
799		const home = homedir();
800		for (const manager of VERSION_MANAGERS) {
801			const read = await readVersionManagerRuntimes(
802				manager,
803				environment,
804				home,
805				platform,
806				architecture,
807			);
808			if (read.present) suppliers.push(manager.supplier);
809			installed.push(...read.runtimes);
810		}
811		return Object.freeze({
812			platform,
813			architecture,
814			runningNodeVersion: runningVersion,
815			runningNodeMajor: runningMajor,
816			suppliers: Object.freeze(suppliers),
817			installed: Object.freeze([...installed].sort(compareRuntimes)),
818		});
819	}
