1041					code: 'era-cell.node-major-sources-disagree',
1042					message: `Era cell: this tree names ${String(distinct.length)} different Node major lines (${distinct.join(', ')}) in ${String(named.length)} of its own declarations — ${named.map(renderNodeMajorSource).join('; ')}. Which one the application was built inside is not something a precedence order settles when the sources contradict each other, so this stage reads none of them; declare it with --node <major>. Every source consulted: ${consulted.map(renderNodeMajorSource).join('; ')}.`,
1043					stage: 'era-cell',
1044					origin: 'pipeline',
1045				});
