1059			refuse({
1060				code: 'era-cell.cell-not-declared-for-framework',
1061				message: `Era cell: the ${analysis.lineage} lineage publishes no target-cell registry this stage can read a Node line out of — ${analysis.cellReadings.reason ?? 'no cell was published for this tree'} — and the tree declares no Node era of its own in .nvmrc, .node-version, package.json#volta.node, .tool-versions, any Dockerfile* FROM a node image, any .github/workflows node-version, or package.json#engines.node. Nothing here names the toolchain era the install stage would run inside; declare it with --cell <id> or --node <major>.`,
1062				stage: 'era-cell',
1063				origin: 'pipeline',
1064			});
