1103			cellSource: declarations.cell === null ? 'inferred' : 'declared',
1104			cellBasis:
1105				cell === null
1106					? `the ${analysis.lineage} lineage publishes no target-cell registry, so the cell is the Node line the tree itself declares. Only a Node runtime is named by it.`
1107					: cell.describedBy,
1108			nodeMajor,
1109			nodeMajorSource,
1110			nodeMajorReadFrom,
1111			nodeMajorSources: consulted,
1112			architecture,
1113			architectureSource,
1114			architectureBasis,
1115			architectureRequirements: frontendRequirements,
1116		});
1117	
1118		const translation = translationFor(reading, architecture);
1119		const candidates = reading.installed.filter(
1120			(runtime) =>
1121				runtime.major === nodeMajor &&
1122				runtime.architecture === architecture &&
1123				runtime.platform === reading.platform,
1124		);
1125		if (candidates.length === 0 && architecture !== reading.architecture)
1126			refuse({
1127				code: 'era-cell.arch-not-available',
1128				message: `Era cell: the cell requires a Node ${String(nodeMajor)} runtime at ${architecture} and this host is ${reading.platform}-${reading.architecture}. The requirement is read rather than assumed: ${sentence(architectureBasis)} ${
1129					translation === null
1130						? `No translation of ${architecture} is available on ${reading.platform}-${reading.architecture}, so there is no remedy available on this host.`
1131						: `${translation} can translate ${architecture} here, but no ${architecture} Node ${String(nodeMajor)} runtime is present at any location this stage reads (${reading.suppliers.join(', ')}), and this stage opens no network to obtain one.`
1132				} The install this cell would run inside is refused before it is attempted rather than after it fails.`,
1133				stage: 'era-cell',
1134				origin: 'pipeline',
1135			});
1136		if (candidates.length === 0)
1137			refuse({
1138				code: 'era-cell.required-node-not-installed',
1139				message: `Era cell: the cell requires Node ${String(nodeMajor)} on ${reading.platform}-${architecture} and no such runtime is present at any location this stage reads (${reading.suppliers.join(', ')}). The runtimes it found are ${
1140					reading.installed.length === 0
1141						? 'none'
1142						: reading.installed
1143								.map(
1144									(runtime) =>
1145										`${runtime.version} ${runtime.platform}-${runtime.architecture} (${runtime.supplier})`,
1146								)
1147								.join(', ')
1148				}. This stage opens no network, so a runtime this host does not already carry is a refusal rather than a fetch.`,
1149				stage: 'era-cell',
1150				origin: 'pipeline',
1151			});
1152	
1153		const running = candidates.find((runtime) => runtime.supplier === RUNNING_PROCESS);
1154		const chosen = running ?? (candidates[0] as InstalledRuntime);
1155		return Object.freeze({
1156			stage: 'era-cell',
1157			schemaVersion: ERA_CELL_RECORD_SCHEMA,
1158			ran: true,
1159			reason: null,
1160			outcome: running === undefined ? 'provisioned' : 'already-present',
1161			required,
1162			determination: Object.freeze({
1163				inferred: Object.freeze([...inferred].sort()),
1164				declared: Object.freeze([...declared].sort()),
1165			}),
1166			host: reading,
1167			provision: Object.freeze({
1168				supplier: chosen.supplier,
1169				version: chosen.version,
1170				location: chosen.location,
1171				translation,
1172			}),
1173			refusal: null,
1174			notEstablished: ERA_CELL_NOT_ESTABLISHED,
1175		});
1176	}
1177	
1178	/** The era-cell record as an operator reads it. */
1179	export function renderEraCell(record: EraCellRecord): string {
1180		if (!record.ran) return `era cell: not run — ${record.reason ?? ''}\n`;
1181		if (record.outcome === 'refused')
1182			return `era cell: refused — ${record.refusal?.code ?? ''}\n${record.refusal?.message ?? ''}\n`;
1183		const required = record.required;
1184		const lines = [
1185			`era cell: ${required?.cell ?? ''} (${required?.cellSource ?? ''})`,
1186			`node: ${String(required?.nodeMajor ?? 0)} (${required?.nodeMajorSource ?? ''}${
1187				required?.nodeMajorReadFrom === null || required?.nodeMajorReadFrom === undefined
1188					? ''
1189					: ` from ${required.nodeMajorReadFrom}`
1190			})`,
1191			...(required?.nodeMajorSources ?? []).map(
1192				(reading) => `node source consulted: ${renderNodeMajorSource(reading)}`,
1193			),
1194			`architecture: ${required?.architecture ?? ''} (${required?.architectureSource ?? ''})`,
1195			`basis: ${required?.architectureBasis ?? ''}`,
1196			`host: ${record.host?.platform ?? ''}-${record.host?.architecture ?? ''}, running ${record.host?.runningNodeVersion ?? ''}; suppliers: ${(record.host?.suppliers ?? []).join(', ')}`,
1197			`outcome: ${record.outcome} — ${record.provision?.supplier ?? ''} ${record.provision?.version ?? ''} at ${record.provision?.location ?? ''}${
1198				record.provision?.translation === null || record.provision?.translation === undefined
1199					? ''
1200					: ` under ${record.provision.translation}`
1201			}`,
1202			'',
1203		];
1204		for (const runtime of record.host?.installed ?? [])
1205			lines.push(
1206				`  ${runtime.version} ${runtime.platform}-${runtime.architecture} (${runtime.supplier}) ${runtime.location}`,
1207			);
1208		lines.push('');
1209		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
1210		return `${lines.join('\n')}\n`;
1211	}
