					schema: 'versionless.run.v1',
					application: 'hand-helped',
					lineage: 'react',
					outcome: 'proceeded',
					/** A count the run states about itself is not the one read. */
					interventions: { count: 0 },
				})}\n`,
			);
			await writeFile(
